const skipStalePracticeActivities = `-- name: SkipStalePracticeActivities :execrows
UPDATE learning_activities a
SET status = 'skipped', completed_at = $3
FROM learning_path_topics t
JOIN learning_paths p ON p.id = t.path_id
WHERE a.teacher_id = $1 AND a.user_id = $2 AND a.type = 'practice' AND a.status = 'open'
  AND a.topic_id = t.id AND p.status <> 'active'
`

type SkipStalePracticeActivitiesParams struct {
	TeacherID   pgtype.UUID
	UserID      pgtype.UUID
	CompletedAt pgtype.Timestamptz
}

// The program was closed with the topic unfinished: the activity is no longer to be done.
func (q *Queries) SkipStalePracticeActivities(ctx context.Context, arg SkipStalePracticeActivitiesParams) (int64, error) {
	result, err := q.db.Exec(ctx, skipStalePracticeActivities, arg.TeacherID, arg.UserID, arg.CompletedAt)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const skipStaleReviewActivities = `-- name: SkipStaleReviewActivities :execrows
UPDATE learning_activities a
SET status = 'skipped', completed_at = $3
FROM learner_item_state s
WHERE a.teacher_id = $1 AND a.user_id = $2 AND a.type = 'review' AND a.status = 'open'
  AND s.teacher_id = a.teacher_id AND s.item_id = a.item_id
  AND (s.due_at IS NULL OR s.due_at > $3)
`

type SkipStaleReviewActivitiesParams struct {
	TeacherID   pgtype.UUID
	UserID      pgtype.UUID
	CompletedAt pgtype.Timestamptz
}

// The item was answered on another way and is not due any more.
func (q *Queries) SkipStaleReviewActivities(ctx context.Context, arg SkipStaleReviewActivitiesParams) (int64, error) {
	result, err := q.db.Exec(ctx, skipStaleReviewActivities, arg.TeacherID, arg.UserID, arg.CompletedAt)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertKBItem = `-- name: UpsertKBItem :one

INSERT INTO learning_knowledge_items (id, language, key, kind, skill, cefr_level, unit, created_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
ON CONFLICT (language, key) DO UPDATE SET key = learning_knowledge_items.key
RETURNING id, language, key, kind, skill, cefr_level, unit, created_at
`

type UpsertKBItemParams struct {
	ID        pgtype.UUID
	Language  string
	Key       string
	Kind      string
	Skill     string
	CefrLevel string
	Unit      string
	CreatedAt pgtype.Timestamptz
}

// The first learning loop: knowledge items, evidence, item state, activities.
// See docs/learning/VERTICAL_SLICE_V1.md. Every query that reads a learner's
// rows is scoped by user_id; an id of another learner is simply not found.
// An item is made from the library the first time the learner shows something
// about it; the no-op update makes the row come back on a repeat.
func (q *Queries) UpsertKBItem(ctx context.Context, arg UpsertKBItemParams) (LearningKnowledgeItem, error) {
	row := q.db.QueryRow(ctx, upsertKBItem,
		arg.ID,
		arg.Language,
		arg.Key,
		arg.Kind,
		arg.Skill,
		arg.CefrLevel,
		arg.Unit,
		arg.CreatedAt,
	)
	var i LearningKnowledgeItem
	err := row.Scan(
		&i.ID,
		&i.Language,
		&i.Key,
		&i.Kind,
		&i.Skill,
		&i.CefrLevel,
		&i.Unit,
		&i.CreatedAt,
	)
	return i, err
}
